// Alexandria — conectar WhatsApp por QR (uma instância por imobiliária)
const ALEX_URL = 'https://yiufxfckyqjrmkkiibfl.supabase.co';
const ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InlpdWZ4ZmNreXFqcm1ra2lpYmZsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3OTIzNDIzMjUsImV4cCI6MjEwNzkxODMyNX0.Nv8kHqpgVmniGJxUmny58Itwxxf_ABI6lUhxzyclbas';
const SEGREDO = 'COLE_AQUI_O_SEGREDO_DO_RELE';            // o mesmo do fluxo que pega a caixa de saída
const WEBHOOK_ENTRADA = 'COLE_AQUI_A_URL_DO_WEBHOOK_DO_NUMERO_MAE'; // a mesma do número mãe (messages.upsert)
const EVO = 'http://evolution-api:8080';
const EVO_KEY = $env.EVOLUTION_API_KEY;

const h = this.helpers;
const rpc = (fn, body) => h.httpRequest({ method: 'POST', url: `${ALEX_URL}/rest/v1/rpc/${fn}`,
  headers: { apikey: ANON, Authorization: `Bearer ${ANON}`, 'Content-Type': 'application/json' }, body, json: true });
const evo = (method, path, body) => h.httpRequest({ method, url: `${EVO}${path}`,
  headers: { apikey: EVO_KEY, 'Content-Type': 'application/json' }, body, json: true });
const atualizar = (empresa, status, extra = {}) => rpc('whatsapp_atualizar',
  { p_segredo: SEGREDO, p_empresa: empresa, p_status: status, p_qr: extra.qr ?? null, p_numero: extra.numero ?? null, p_erro: extra.erro ?? null });

const pendentes = await rpc('whatsapp_pendentes', { p_segredo: SEGREDO });
const saida = [];
for (const p of pendentes) {
  const nome = p.instancia;
  try {
    if (p.status === 'desconectar') {
      try { await evo('DELETE', `/instance/logout/${nome}`); } catch (e) {}
      await atualizar(p.empresa_id, 'desconectado');
      saida.push({ json: { nome, feito: 'desconectado' } });
      continue;
    }
    if (p.status === 'qr') {
      // já tem QR na tela: confere se o cliente leu
      const st = await evo('GET', `/instance/connectionState/${nome}`);
      if ((st.instance?.state || st.state) === 'open') {
        let numero = null;
        try {
          const lista = await evo('GET', `/instance/fetchInstances?instanceName=${nome}`);
          const i = Array.isArray(lista) ? lista[0] : lista;
          numero = (i?.ownerJid || i?.instance?.owner || '').split('@')[0] || null;
        } catch (e) {}
        await atualizar(p.empresa_id, 'conectado', { numero });
        saida.push({ json: { nome, feito: 'conectado' } });
        continue;
      }
    }
    if (p.status === 'pedido') {
      try {
        await evo('POST', '/instance/create', { instanceName: nome, qrcode: true, integration: 'WHATSAPP-BAILEYS',
          webhook: { url: WEBHOOK_ENTRADA, byEvents: false, base64: false, events: ['MESSAGES_UPSERT'] } });
      } catch (e) { /* já existe: só pede o QR de novo */ }
    }
    const c = await evo('GET', `/instance/connect/${nome}`);
    const qr = c.base64 || c.qrcode?.base64 || null;
    if (qr) { await atualizar(p.empresa_id, 'qr', { qr }); saida.push({ json: { nome, feito: 'qr' } }); }
    else if (c.instance?.state === 'open') { await atualizar(p.empresa_id, 'conectado'); saida.push({ json: { nome, feito: 'ja-conectado' } }); }
  } catch (e) {
    try { await atualizar(p.empresa_id, 'erro', { erro: String(e.message || e).slice(0, 200) }); } catch (_) {}
    saida.push({ json: { nome, erro: String(e.message || e) } });
  }
}
return saida;
